import type {AudioDefinition, AudioDirection, AudioManifest} from '@roomriddle/shared-types';

/**
 * How The Last Train sounds (Phase 7): every sound by stable id, and which
 * plays where. PLACEHOLDERS generated by apps/tv/scripts/gen-placeholder-audio.py
 * (synthesised ambience/music/effects; detective lines voiced with edge-tts).
 * Final audio: replace the file of the same name, set status 'final'.
 */
const GEN = 'Generated placeholder (RoomRiddle, gen-placeholder-audio.py); replace before release.';
const TTS = 'Placeholder voice: Microsoft Edge neural TTS (en-GB-RyanNeural) via edge-tts; replace with a recorded performance.';

const s = (id: string, channel: AudioDefinition['channel'], description: string, extra: Partial<AudioDefinition> = {}): AudioDefinition => {
  const [, kind, name] = id.split('.');
  return {
    id,
    channel,
    loop: channel === 'music' || channel === 'ambient',
    status: 'placeholder',
    source: `${kind}-${name}.mp3`,
    description,
    license: channel === 'voice' ? TTS : GEN,
    ...extra,
  };
};

const vo = (name: string, durationMs: number) => s(`last-train.vo.${name}`, 'voice', `Detective: line ${name}.`, {durationMs});

